export { chainFocus, isValidUrl } from "./commands";
export { extensionPresent, nodeActive } from "./detection";
export { shallowEqual, useEditorState } from "./editor-state";
export { DEFAULT_EXTENSION_LABELS } from "./labels";
export type { ExtensionLabelKey, ExtensionLabels } from "./labels";
export { ToolbarProvider, useToolbar, useToolbarEditor } from "./context";
export type { ToolbarContextValue, ToolbarProviderProps } from "./context";
export type { ToolbarComponentProps } from "./types";

import type { ChainedCommands, Editor } from "@tiptap/core";

export const chainFocus = (editor: Editor): ChainedCommands =>
  editor.chain().focus();

export const isValidUrl = (url: string): boolean =>
  /^https?:\/\/\S+$/.test(url);

import type { Editor } from "@tiptap/core";
import type { ReactNode } from "react";
import { createContext, useContext, useMemo } from "react";

import type { ExtensionLabels } from "./labels";
import { DEFAULT_EXTENSION_LABELS } from "./labels";

export interface ToolbarContextValue {
  editor: Editor | null;
  labels: ExtensionLabels;
}

const ToolbarContext = createContext<ToolbarContextValue>({
  editor: null,
  labels: DEFAULT_EXTENSION_LABELS,
});

export interface ToolbarProviderProps {
  children: ReactNode;
  editor?: Editor | null;
  labels?: Partial<ExtensionLabels>;
}

export const ToolbarProvider = ({
  children,
  editor = null,
  labels,
}: ToolbarProviderProps) => {
  const value = useMemo(
    () => ({
      editor,
      labels: { ...DEFAULT_EXTENSION_LABELS, ...labels },
    }),
    [editor, labels]
  );

  return (
    <ToolbarContext.Provider value={value}>
      {children}
    </ToolbarContext.Provider>
  );
};

export const useToolbar = (): ToolbarContextValue =>
  useContext(ToolbarContext);

export const useToolbarEditor = (
  editor: Editor | null | undefined
): Editor | null => {
  const context = useContext(ToolbarContext);
  return editor ?? context.editor ?? null;
};

import type { Editor } from "@tiptap/core";

export const extensionPresent = (
  editor: Editor | null,
  name: string
): boolean =>
  Boolean(
    editor &&
    !editor.isDestroyed &&
    editor.extensionManager.extensions.some(
      (extension) => extension.name === name
    )
  );

export const nodeActive = (
  editor: Editor | null,
  name: string,
  attributes?: Record<string, unknown>
): boolean =>
  Boolean(editor && !editor.isDestroyed && editor.isActive(name, attributes));

import type { Editor } from "@tiptap/core";
import { useCallback, useRef, useSyncExternalStore } from "react";

const defaultEqual = <T>(a: T, b: T): boolean => a === b;

export const shallowEqual = <T extends Record<string, unknown>>(
  a: T,
  b: T
): boolean => {
  if (a === b) {
    return true;
  }
  if (!a || !b) {
    return false;
  }
  const ak = Object.keys(a);
  const bk = Object.keys(b);
  if (ak.length !== bk.length) {
    return false;
  }
  return ak.every((k) => a[k] === b[k]);
};

const isPlainEmpty = <T>(value: T | undefined): value is undefined =>
  value === undefined;

export const useEditorState = <T>(
  editor: Editor | null,
  selector: (e: Editor) => T,
  isEqual: (a: T, b: T) => boolean = defaultEqual
): T | undefined => {
  const selectorRef = useRef(selector);
  const isEqualRef = useRef(isEqual);
  selectorRef.current = selector;
  isEqualRef.current = isEqual;

  const snapshotRef = useRef<{ value: T | undefined }>({
    value: editor ? selector(editor) : undefined,
  });

  const computeSnapshot = useCallback((): T | undefined => {
    if (!editor) {
      return undefined;
    }
    const next = selectorRef.current(editor);
    const current = snapshotRef.current.value;
    if (isPlainEmpty(current) || !isEqualRef.current(current, next)) {
      snapshotRef.current.value = next;
    }
    return snapshotRef.current.value;
  }, [editor]);

  const subscribe = useCallback(
    (onStoreChange: () => void) => {
      if (!editor) {
        return () => {};
      }
      const update = () => {
        computeSnapshot();
        onStoreChange();
      };
      editor.on("selectionUpdate", update);
      editor.on("transaction", update);
      return () => {
        editor.off("selectionUpdate", update);
        editor.off("transaction", update);
      };
    },
    [editor, computeSnapshot]
  );

  return useSyncExternalStore(subscribe, computeSnapshot, computeSnapshot);
};

export interface ExtensionLabels {
  addColumnLeft: string;
  addColumnRight: string;
  addRowAbove: string;
  addRowBelow: string;
  columns: string;
  deleteColumn: string;
  deleteRow: string;
  deleteTable: string;
  headerRow: string;
  highlightColor: string;
  image: string;
  imagePlaceholder: string;
  insertTable: string;
  mergeCells: string;
  removeHighlight: string;
  rows: string;
  splitCell: string;
}

export type ExtensionLabelKey = keyof ExtensionLabels;

export const DEFAULT_EXTENSION_LABELS: ExtensionLabels = {
  addColumnLeft: "Add column left",
  addColumnRight: "Add column right",
  addRowAbove: "Add row above",
  addRowBelow: "Add row below",
  columns: "Columns",
  deleteColumn: "Delete column",
  deleteRow: "Delete row",
  deleteTable: "Delete table",
  headerRow: "Header row",
  highlightColor: "Highlight color",
  image: "Image",
  imagePlaceholder: "Add an image",
  insertTable: "Insert table",
  mergeCells: "Merge cells",
  removeHighlight: "Remove highlight",
  rows: "Rows",
  splitCell: "Split cell",
};

import type { Editor } from "@tiptap/core";

export interface ToolbarComponentProps {
  className?: string;
  editor?: Editor | null;
  size?: "icon" | "icon-lg" | "icon-sm";
}

import { Highlight as TiptapHighlight } from "@tiptap/extension-highlight";

export const Highlight = TiptapHighlight.configure({
  multicolor: true,
});

"use client";

import { Button } from "@components/extensions/ui/button";
import { cn } from "@/lib/utils";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@components/extensions/ui/popover";
import { Highlighter } from "lucide-react";

import { useToolbar, useToolbarEditor } from "../core/context";
import { extensionPresent } from "../core/detection";
import { shallowEqual, useEditorState } from "../core/editor-state";
import type { ToolbarComponentProps } from "../core/types";

const HIGHLIGHT_COLORS = [
  { color: "#fef08a", label: "Yellow" },
  { color: "#bbf7d0", label: "Green" },
  { color: "#bfdbfe", label: "Blue" },
  { color: "#fbcfe8", label: "Pink" },
] as const;

export const HighlightToolbar = ({
  className,
  editor: editorProp,
}: ToolbarComponentProps) => {
  const { labels } = useToolbar();
  const editor = useToolbarEditor(editorProp);

  const { activeColor, disabled } = useEditorState(
    editor,
    (edit) => ({
      activeColor: edit.isActive("highlight")
        ? (edit.getAttributes("highlight").color as string | undefined)
        : undefined,
      disabled: !extensionPresent(edit, "highlight"),
    }),
    shallowEqual
  ) ?? { activeColor: undefined, disabled: true };

  return (
    <Popover>
      <PopoverTrigger
        disabled={disabled}
        render={
          <Button
            aria-label={labels.highlightColor}
            className={className}
            data-active={activeColor ? "true" : undefined}
            disabled={disabled}
            size="icon-sm"
            title={labels.highlightColor}
            variant="ghost"
          />
        }
      >
        <Highlighter />
      </PopoverTrigger>
      <PopoverContent align="start" className="w-auto gap-2" sideOffset={6}>
        <div className="grid grid-cols-4 gap-2">
          {HIGHLIGHT_COLORS.map((item) => (
            <button
              key={item.color}
              aria-label={item.label}
              className={cn(
                "size-6 rounded-full border border-black/10 outline-none transition-transform hover:scale-110 focus-visible:ring-2 focus-visible:ring-ring",
                activeColor === item.color && "ring-2 ring-ring ring-offset-2"
              )}
              style={{ backgroundColor: item.color }}
              title={item.label}
              type="button"
              onClick={() => {
                if (editor && !editor.isDestroyed) {
                  editor
                    .chain()
                    .focus()
                    .setHighlight({ color: item.color })
                    .run();
                }
              }}
            />
          ))}
        </div>
        {activeColor ? (
          <Button
            className="w-full"
            size="sm"
            type="button"
            variant="ghost"
            onClick={() => {
              if (editor && !editor.isDestroyed) {
                editor.chain().focus().unsetHighlight().run();
              }
            }}
          >
            {labels.removeHighlight}
          </Button>
        ) : null}
      </PopoverContent>
    </Popover>
  );
};

"use client";

import { Popover as PopoverPrimitive } from "@base-ui/react/popover";
import { cn } from "@/lib/utils";
import * as React from "react";

const Popover = ({ ...props }: PopoverPrimitive.Root.Props) => (
  <PopoverPrimitive.Root data-slot="popover" {...props} />
);

const PopoverTrigger = ({ ...props }: PopoverPrimitive.Trigger.Props) => (
  <PopoverPrimitive.Trigger data-slot="popover-trigger" {...props} />
);

const PopoverContent = ({
  className,
  align = "center",
  alignOffset = 0,
  side = "bottom",
  sideOffset = 4,
  ...props
}: PopoverPrimitive.Popup.Props &
  Pick<
    PopoverPrimitive.Positioner.Props,
    "align" | "alignOffset" | "side" | "sideOffset"
  >) => (
  <PopoverPrimitive.Portal>
    <PopoverPrimitive.Positioner
      align={align}
      alignOffset={alignOffset}
      side={side}
      sideOffset={sideOffset}
      className="isolate z-50"
    >
      <PopoverPrimitive.Popup
        data-slot="popover-content"
        className={cn(
          "z-50 flex w-72 origin-(--transform-origin) flex-col gap-4 rounded-md bg-popover p-4 text-sm text-popover-foreground shadow-md ring-1 ring-foreground/10 outline-hidden duration-100 data-[side=bottom]:slide-in-from-top-2 data-[side=inline-end]:slide-in-from-left-2 data-[side=inline-start]:slide-in-from-right-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-open:animate-in data-open:fade-in-0 data-open:zoom-in-95 data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-95",
          className
        )}
        {...props}
      />
    </PopoverPrimitive.Positioner>
  </PopoverPrimitive.Portal>
);

const PopoverHeader = ({
  className,
  ...props
}: React.ComponentProps<"div">) => (
  <div
    data-slot="popover-header"
    className={cn("flex flex-col gap-1 text-sm", className)}
    {...props}
  />
);

const PopoverTitle = ({
  className,
  ...props
}: PopoverPrimitive.Title.Props) => (
  <PopoverPrimitive.Title
    data-slot="popover-title"
    className={cn("font-medium", className)}
    {...props}
  />
);

const PopoverDescription = ({
  className,
  ...props
}: PopoverPrimitive.Description.Props) => (
  <PopoverPrimitive.Description
    data-slot="popover-description"
    className={cn("text-muted-foreground", className)}
    {...props}
  />
);

export {
  Popover,
  PopoverContent,
  PopoverDescription,
  PopoverHeader,
  PopoverTitle,
  PopoverTrigger,
};

